head.script:
scwin.gVar = {
    "cAnimationColor" : "",
    "cAnimationType" : "",
    "cClass" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[trigger > P > animationType]<br/>컴포넌트를 클릭(터치) 시 재생될 애니메이션 효과를 설정합니다.",
    "validation" : [
        "type=anchor 이고, class 속성에 btn_bubble 을 설정한 경우에 동작합니다.",
        "'bubble' 설정 시 클릭(터치) 위치에서 원이 퍼져 나가는 애니메이션 효과가 적용되어야 합니다.",
        "'' 설정 시 애니메이션 효과가 적용되지 않아야 합니다.",
        "미설정 시 애니메이션 효과가 적용되지 않아야 합니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {    
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        animationColor : scwin.gVar["cAnimationColor"],
        animationType : scwin.gVar["cAnimationType"],
        type : "anchor",
        class : scwin.gVar["cClass"],
        style : "width:150px; height:50px;",
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출
    $c.gcm.createEmptyTrigger(cList);
}
